def chunk(xs, n):
    """
    Split 'xs' into consecutive lists of length 'n'.
    The last list may be shorter if there are not enough elements.
    If 'xs' is empty, an empty list is returned.
    Raises ValueError if n < 1.
    """
    if n < 1:
        raise ValueError("n must be >= 1")

    it = iter(xs)
    result = []

    while True:
        current = []
        for _ in range(n):
            try:
                current.append(next(it))
            except StopIteration:
                if current:
                    result.append(current)
                return result
        result.append(current)
